# DK FBN.  Frederiksberg - Frederiksberg Nord
#
let fn = path("d3.dk.fbn");

with detail = 4, railway = :first :nopax :removed {
    with link = "line.dk.FBN" {
        with layer = -3 track(:station,
                fn[:fre.yn - 0.1dl, :fre.yn] >> 0.5mo
            ..  fn[:frn - 0.6dl, :frn - 0.5dl] >> 1.5mo
        );
    }
}

